link.script:
// Lazy-load AdSense: defer the library until an ad nears the viewport or the
// user interacts. Keeps adsbygoogle.js off the critical path (better LCP/TBT)
// while the inline push({}) calls on each  simply stay queued until then.
(function () {
    var loaded = false;
    var events = ['scroll', 'mousemove', 'touchstart', 'keydown'];
    function cleanup() {
        events.forEach(function (e) { window.removeEventListener(e, load); });
    }
    function load() {
        if (loaded) { return; }
        loaded = true;
        cleanup();
        var s = document.createElement('script');
        s.async = true;
        s.crossOrigin = 'anonymous';
        s.setAttribute('data-ad-client', 'ca-pub-3487578908915396');
        s.src = 'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js';
        document.head.appendChild(s);
    }
    function observe() {
        var ads = document.getElementsByClassName('adsbygoogle');
        if (!ads.length) { return; }
        if (!('IntersectionObserver' in window)) { load(); return; }
        var io = new IntersectionObserver(function (entries) {
            for (var i = 0; i < entries.length; i++) {
                if (entries[i].isIntersecting) { load(); io.disconnect(); return; }
            }
        }, { rootMargin: '600px 0px' });
        for (var j = 0; j < ads.length; j++) { io.observe(ads[j]); }
    }
    events.forEach(function (e) { window.addEventListener(e, load, { passive: true }); });
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', observe);
    } else {
        observe();
    }
})();

{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Organization",
      "@id": "https://cdnlogo.com/#organization",
      "name": "CDNLogo.com",
      "url": "https://cdnlogo.com/",
      "logo": {
        "@type": "ImageObject",
        "url": "https://www.cdnlogo.com/assets/images/logo.svg"
      },
      "sameAs": [
        "https://www.facebook.com/cdnlogo",
        "https://x.com/cdnlogo",
        "https://www.pinterest.com/cdnlogo"
      ]
    },
    {
      "@type": "WebSite",
      "@id": "https://cdnlogo.com/#website",
      "url": "https://cdnlogo.com/",
      "name": "CDNLogo.com",
      "description": "CDNLogo is largest brands logo vectors of the world. Logos can filter by colors, download in SVG, EPS, AI and PNG format. No login required and unlimited downloads.",
      "publisher": {
        "@id": "https://cdnlogo.com/#organization"
      },
      "potentialAction": {
        "@type": "SearchAction",
        "target": {
          "@type": "EntryPoint",
          "urlTemplate": "https://cdnlogo.com/vector-logos/{search_term_string}"
        },
        "query-input": "required name=search_term_string"
      },
      "inLanguage": "en"
    }  ]
}
